<?php
/** Proof — the OS statement (spec "Proof", 4): the fake kernel's two months (2026-08 closed, 2026-09 open); Pull keeps the closed one verbatim (hash, lines) and shows the open one open; Allocate refuses the open one; rules 60/40 → four drafts and the remainder to the cent; a rule added → Re-allocate keeps the approved charge and remakes the drafts; rules over 100 % refused by name; the kernel down → 503 in words, nothing changed; a changed document for an allocated month refused; an open month closing. */
require __DIR__ . '/lib.php';
[$acme, $beta] = usage_world();
$priya = as_member(26); $marco = as_member(27); $bea = as_member(28); $ann = as_member(29);
$docs = ledger_fixture();
$klog = need('FAKE_KERNEL_STATE') . '.ledger';
@unlink($klog);
function asked(): array { return array_values(array_filter(array_map('trim', file(need('FAKE_KERNEL_STATE') . '.ledger') ?: []))); }
function rule_req(string $jar, array $extra): array { return act($jar, '/settings/allocation-rules/save.php', array_merge(['valid_from' => '2026-01-01'], $extra)); }

echo "1. Who may\n";
[$c, $b] = act($priya, '/usage/os/pull.php', []);
ok($c === 403 && msg($b) === 'You may not record usage charges.', 'Priya: ai_statement_pull → 403');
ok(page($priya, '/usage/os')['code'] === 403 && page($ann, '/usage/os')['code'] === 403, 'the screen: 403 for Priya and for Ann (Finance has no usage.write)');
[$c, $b] = act($priya, '/usage/os/allocate.php', ['period' => '2026-08']);
ok($c === 403, 'Priya: ai_statement_allocate → 403');

echo "2. The kernel unreachable: a 503 in words, nothing changed\n";
set_ledger($docs, 'down');
[$c, $b] = act($marco, '/usage/os/pull.php', []);
ok($c === 503 && ($b['error']['code'] ?? '') === 'unavailable' && str_contains(msg($b), 'The OS answered 503'), 'the kernel answers 503: 503 in words (' . msg($b) . ')');
set_ledger($docs);
$pid = (int) trim((string) @file_get_contents(need('CT_DEV_STATE') . '/kernel.pid'));
exec('kill ' . $pid . ' 2>/dev/null; sleep 0.5; pkill -f "php -S 127.0.0.1:830[2] " 2>/dev/null; sleep 0.3');
$since = last_activity_id();
[$c, $b] = act($marco, '/usage/os/pull.php', []);
ok($c === 503 && str_contains(msg($b), 'The OS could not be reached, so nothing was pulled'), 'the kernel not running at all: 503 "The OS could not be reached, so nothing was pulled" (' . msg($b) . ')');
ok((int) one('SELECT count(*) FROM ai_statements') === 0 && count(activity('ai_statement.pull', $since)) === 0, 'nothing was pulled, nothing logged');
$cmd = 'cd ' . escapeshellarg(dirname(__DIR__, 3)) . ' && FAKE_KERNEL_STATE=' . escapeshellarg(need('FAKE_KERNEL_STATE')) . ' OS_APPLICATION_TOKEN=' . escapeshellarg(need('OS_APPLICATION_TOKEN')) . ' nohup php -S 127.0.0.1:8302 tests/fake_kernel.php > /dev/null 2>&1 & echo $!';
file_put_contents(need('CT_DEV_STATE') . '/kernel.pid', trim((string) shell_exec($cmd)));
for ($i = 0; $i < 30; $i++) { if (@file_get_contents('http://127.0.0.1:8302/') !== false || str_contains((string) ($http_response_header[0] ?? ''), '401')) { break; } usleep(200000); }

echo "3. Pull: the closed month kept verbatim, the open one shown open\n";
@unlink($klog);
$since = last_activity_id();
[$c, $b] = act($marco, '/usage/os/pull.php', []);
ok($c === 200 && count($b['months']) === 2 && ($b['refresh'] ?? '') === 'usageChanged' && ($b['location'] ?? '') === '/usage/os?notice=pulled', 'ai_statement_pull: 200, two months touched');
$aug = statement_row('2026-08'); $sep = statement_row('2026-09');
ok($aug['kernel_status'] === 'closed' && $aug['status'] === 'pulled' && $sep['kernel_status'] === 'open' && $sep['status'] === 'pulled' && $aug['period_start'] === '2026-08-01' && $aug['period_end'] === '2026-08-31', '2026-08 is closed in the OS, 2026-09 open; both pulled here');
ok(json_decode($aug['document'], true) == $docs['2026-08'] && $aug['document_hash'] === (string) one("SELECT encode(sha256(convert_to(document::text, 'UTF8')), 'hex') FROM ai_statements WHERE period = '2026-08'") && strlen($aug['document_hash']) === 64, 'the closed month is kept verbatim: the stored document equals the kernel\'s, and the hash is the SHA-256 of what is stored');
$lines = q('SELECT * FROM ai_statement_lines WHERE statement_id = :s ORDER BY line_no', ['s' => $aug['id']]);
ok(count($lines) === 3 && $lines[0]['provider'] === 'anthropic' && (int) $lines[0]['kernel_agent_id'] === 901 && $lines[0]['agent'] === 'Researcher' && (int) $lines[0]['kernel_department_id'] === 7 && $lines[0]['department'] === 'AI Strategy' && (int) $lines[0]['kernel_application_id'] === 3 && $lines[0]['application'] === 'Projects'
    && $lines[0]['amount'] === '100.0000' && (int) $lines[0]['input_tokens'] === 800000 && $lines[1]['provider'] === 'openai' && $lines[1]['amount'] === '30.3350' && $lines[2]['agent'] === 'Writer' && (int) $lines[2]['kernel_department_id'] === 8, 'its three lines, with the kernel\'s ids and names, tokens and the amounts to four decimals');
$log = activity('ai_statement.pull', $since);
$by = [];
foreach ($log as $l) { $a = json_decode((string) $l['after'], true); $by[$a['period']] = $a; }
ok(count($log) === 2 && $by['2026-08']['lines'] === 3 && $by['2026-08']['hash'] === $aug['document_hash'] && $by['2026-08']['new'] === true && $by['2026-08']['kernel_status'] === 'closed' && $by['2026-09']['kernel_status'] === 'open' && $log[0]['entity_type'] === 'ai_statement' && $log[0]['engagement_id'] === null, 'ai_statement.pull logged per month: period, kernel_status, status, lines, hash, new');
ok(asked() === ['list', '2026-09', '2026-08'] || asked() === ['list', '2026-08', '2026-09'] || (count(asked()) === 3 && asked()[0] === 'list'), 'the kernel was asked for the months, then each one it had not delivered');
@unlink($klog);
[$c, $b] = act($marco, '/usage/os/pull.php', []);
ok($c === 200 && count($b['months']) === 1 && $b['months'][0]['period'] === '2026-09' && $b['months'][0]['new'] === false && $b['months'][0]['changed'] === false && asked() === ['list', '2026-09'], 'pulling again asks only for what may still move: the open month (a closed, pulled month is left alone); nothing changed');
[$c, $b] = act($marco, '/usage/os/pull.php', ['period' => '2026-08']);
ok($c === 200 && $b['months'][0]['changed'] === false && statement_row('2026-08')['document_hash'] === $aug['document_hash'], 'pulling one month by name: the same document, the same hash');
[$c, $b] = act($marco, '/usage/os/pull.php', ['period' => '2026-13']);
ok($c === 422 && msg($b) === 'A month is written YYYY-MM.', 'a bad month: 422 in words');
[$c, $b] = act($marco, '/usage/os/pull.php', ['period' => '2025-01']);
ok($c === 422 && str_contains(msg($b), 'The OS has no statement for 2025-01'), 'a month the kernel has none of: 422 in words (' . msg($b) . ')');

echo "4. The screen: the months, one opened\n";
[$c, $d] = screen($marco, '/usage/os');
$m = array_column($d['months'], null, 'period');
ok($c === 200 && count($d['months']) === 2 && $m['2026-08']['kernel_status'] === 'closed' && $m['2026-09']['kernel_status'] === 'open' && $m['2026-08']['statement_amount'] === '180.34' && $m['2026-08']['allocated_amount'] === '0.00' && $m['2026-08']['remainder'] === '180.34' && $m['2026-08']['lines'] === 3, 'the months (JSON): status in the OS, ours, the statement total 180.34 (100.00 + 30.34 + 50.00), nothing allocated');
$body = page($marco, '/usage/os')['body'];
ok(str_contains($body, 'id="os-pull-btn"') && str_contains($body, 'id="statement-' . $aug['id'] . '"') && str_contains($body, 'id="statement-' . $sep['id'] . '-kernel">open in the OS<'), 'the page: Pull, a row per month, the open one says "open in the OS"');
$body = page($marco, '/usage/os?period=2026-09')['body'];
ok(str_contains($body, 'id="os-month-open"') && str_contains($body, 'Not yet closed in the OS') && !str_contains($body, 'id="os-allocate-btn"'), 'the open month says "Not yet closed in the OS" and offers no Allocate');
$body = page($marco, '/usage/os?period=2026-08')['body'];
ok(str_contains($body, 'id="os-allocate-btn"') && str_contains($body, 'id="statement-line-' . $lines[0]['id'] . '"') && str_contains($body, 'id="os-month-norules"'), 'the closed month: its lines, Allocate, and a hint that no rule is active');
[$c, $b] = act($marco, '/usage/os/allocate.php', ['period' => '2026-09']);
ok($c === 422 && msg($b) === 'Statement 2026-09 is still open in the OS; only a closed month is allocated', 'Allocate on the open month: the database\'s words (' . msg($b) . ')');
[$c, $b] = act($marco, '/usage/os/allocate.php', ['statement' => 999999]);
ok($c === 404, 'a statement that is not there: 404');
[$c, $b] = act($marco, '/usage/os/allocate.php', []);
ok($c === 422, 'no month named: 422');

echo "5. Rules 60/40: four drafts and the remainder to the cent\n";
[$c, $b] = rule_req($priya, ['name' => 'SMOKE r', 'engagement' => $acme, 'agent' => 901]);
ok($c === 403, 'Priya: allocation_rule_save → 403');
$since = last_activity_id();
[$c, $b] = rule_req($marco, ['name' => 'SMOKE Researcher 60 to Acme', 'engagement' => $acme, 'agent' => 901, 'share_pct' => '60']);
$r1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $r1 > 0 && ($b['location'] ?? '') === '/settings/allocation-rules/?notice=saved', 'allocation_rule_save: 200');
$log = activity('allocation_rule.save', $since);
ok(count($log) === 1 && (int) $log[0]['engagement_id'] === $acme && json_decode((string) $log[0]['after'], true)['share_pct'] === '60.00' && json_decode((string) $log[0]['after'], true)['kernel_agent_id'] === 901 && json_decode((string) $log[0]['after'], true)['name'] === 'SMOKE Researcher 60 to Acme', 'allocation_rule.save logged with the engagement, the kernel id, the share');
[$c, $b] = rule_req($marco, ['name' => 'SMOKE Researcher 40 to Beta', 'engagement' => $beta, 'agent' => 901, 'share_pct' => '40', 'pricing' => 'markup', 'markup_pct' => '25']);
$r2 = (int) $b['record_id'];
[$c, $b] = rule_req($marco, ['name' => 'nothing named', 'engagement' => $acme]);
ok($c === 422 && isset(fields($b)['agent']), 'a rule that names no agent, department or application: 422');
[$c, $b] = rule_req($marco, ['name' => 'too big', 'engagement' => $acme, 'agent' => 901, 'share_pct' => '120']);
ok($c === 422 && isset(fields($b)['share_pct']), 'a share over 100: 422');
[$c, $b] = rule_req($marco, ['name' => 'backwards', 'engagement' => $acme, 'agent' => 901, 'valid_to' => '2025-01-01']);
ok($c === 422 && isset(fields($b)['valid_to']), 'an end before the start: 422');
[$c, $d] = screen($marco, '/settings/allocation-rules/');
ok($c === 200 && count($d['rules']) === 2 && $d['names']['agent'][901] === 'Researcher' && $d['names']['department'][8] === 'Content' && $d['rules'][0]['last'] === null, 'the rules (JSON): two, the names the statement carried for the kernel ids, nothing placed yet');
$body = page($marco, '/settings/allocation-rules/')['body'];
ok(str_contains($body, 'id="rule-row-' . $r1 . '"') && str_contains($body, 'Agent Researcher') && str_contains($body, 'id="rule-row-' . $r1 . '-share">60 %<'), 'the page: a card per rule, the agent by the name the statement carried');
$since = last_activity_id();
$before = (int) one('SELECT count(*) FROM notifications');
[$c, $b] = act($bea, '/usage/os/allocate.php', ['period' => '2026-08']);
ok($c === 200 && $b['charges'] === 4 && $b['kept'] === 0 && $b['allocated_amount'] === '130.33' && $b['remainder'] === '50.01' && $b['currency'] === 'USD', 'ai_statement_allocate (Bea): four draft charges, 130.33 placed, remainder 50.01 (the Writer\'s 50.00 and one cent of rounding)');
$sum = array_column($b['summary'], null, 'provider');
ok($sum['anthropic']['statement_amount'] === '150.00' && $sum['anthropic']['allocated_amount'] === '100.00' && $sum['anthropic']['remainder'] === '50.00' && $sum['openai']['statement_amount'] === '30.34' && $sum['openai']['allocated_amount'] === '30.33' && $sum['openai']['remainder'] === '0.01', 'the summary per provider: anthropic 150.00 / 100.00 / 50.00; openai 30.34 / 30.33 / 0.01 (60 % of 30.335 = 18.20, 40 % = 12.13, rounded once, the cent stays in the remainder)');
$ch = q("SELECT u.*, p.provider_key FROM usage_charges u JOIN usage_providers p ON p.id = u.provider_id WHERE u.statement_id = :s ORDER BY u.engagement_id, p.provider_key", ['s' => $aug['id']]);
ok(count($ch) === 4 && array_column($ch, 'cost_amount') === ['60.00', '18.20', '40.00', '12.13'] && array_column($ch, 'billable_amount') === ['60.00', '18.20', '50.00', '15.16'] && array_unique(array_column($ch, 'status')) === ['draft'] && array_unique(array_column($ch, 'source')) === ['kernel_ledger'] && array_unique(array_column($ch, 'unit')) === ['tokens']
    && array_unique(array_column($ch, 'period_start')) === ['2026-08-01'] && array_unique(array_column($ch, 'period_end')) === ['2026-08-31'] && array_column($ch, 'quantity') === ['600000.0000', '600000.0000', '400000.0000', '400000.0000'], 'the four drafts: Acme anthropic 60.00 and openai 18.20 at cost; Beta anthropic 40.00 and openai 12.13 at cost plus 25 % (50.00 and 15.16); tokens pro rata; the month as the period; source kernel_ledger');
$alloc = q('SELECT count(*) AS n, sum(amount) AS s FROM ai_statement_allocations WHERE statement_id = :s', ['s' => $aug['id']])[0];
$ln = q('SELECT line_no, allocated_amount FROM ai_statement_lines WHERE statement_id = :s ORDER BY line_no', ['s' => $aug['id']]);
ok((int) $alloc['n'] === 4 && $alloc['s'] === '130.33' && array_column($ln, 'allocated_amount') === ['100.00', '30.33', '0.00'] && statement_row('2026-08')['status'] === 'allocated' && (int) statement_row('2026-08')['allocated_by'] === 28, 'four pieces of 130.33 in all; the lines carry their allocated amounts; the month is allocated, by Bea');
$log = activity('ai_statement.allocate', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $log[0]['entity_type'] === 'ai_statement' && (int) $log[0]['entity_id'] === (int) $aug['id'] && $after['period'] === '2026-08' && $after['charges'] === 4 && $after['allocated_amount'] === '130.33' && $after['remainder'] === '50.01' && $after['currency'] === 'USD' && $after['amount'] === '130.33', 'ai_statement.allocate logged: period, charges, kept, allocated_amount, remainder, currency, amount');
$told = q("SELECT member_id, record_type, record_id, title FROM notifications WHERE kind = 'ai_statement_allocated' AND id > :b", ['b' => $before]);
ok(count($told) === 1 && $told[0]['member_id'] === 27 && $told[0]['record_type'] === 'ai_statement' && (int) $told[0]['record_id'] === (int) $aug['id'] && str_contains($told[0]['title'], '4 draft charges') && str_contains($told[0]['title'], 'ENG-'), 'Marco (the manager of both) is told once: ai_statement_allocated, "' . ($told[0]['title'] ?? '') . '"');
[$c, $d] = screen($marco, '/usage/os?period=2026-08');
ok($c === 200 && count($d['lines']) === 3 && $d['lines'][1]['remainder'] === '0.01' && $d['lines'][2]['remainder'] === '50.00' && $d['lines'][0]['remainder'] === '0.00' && count($d['charges']) === 4 && $d['month']['status'] === 'allocated' && $d['month']['remainder'] === '50.01', 'the month opened (JSON): the lines with their remainders (0.00, 0.01, 50.00), the four charges it made');
$body = page($marco, '/usage/os?period=2026-08')['body'];
ok(str_contains($body, '>Re-allocate<') && str_contains($body, 'id="statement-line-' . $lines[1]['id'] . '-remainder"') && str_contains($body, 'id="os-charge-' . $ch[0]['id'] . '"'), 'the page: Re-allocate, the lines\' remainders, the charges listed');
[$c, $d] = screen($marco, '/settings/allocation-rules/');
$placed = array_column($d['rules'], 'last', 'rule_id');
ok($placed[$r1]['period'] === '2026-08' && $placed[$r1]['amount'] === '78.20' && $placed[$r2]['amount'] === '52.13', 'each rule shows what it placed on the last allocated month (78.20 and 52.13)');
[$c, $d] = screen($marco, '/usage/' . $ch[0]['id']);
ok($c === 200 && $d['statement']['period'] === '2026-08' && count($d['pieces']) === 1 && $d['pieces'][0]['rule']['name'] === 'SMOKE Researcher 60 to Acme' && $d['pieces'][0]['amount'] === '60.00' && $d['pieces'][0]['agent'] === 'Researcher', 'a kernel charge\'s page: the statement, the piece, the rule behind it');
$page = page($marco, '/usage/' . $ch[0]['id'])['body'];
ok(str_contains($page, 'id="usage-source-statement"') && str_contains($page, 'id="usage-pieces"'), 'its page shows the statement lines and rules behind it');
[$c, $b] = act($marco, '/usage/delete.php', ['charge' => (int) $ch[0]['id']]);
ok($c === 422 && str_contains(msg($b), 'came from the OS statement; void it'), 'a charge from the statement is voided, never deleted (' . msg($b) . ')');

echo "6. A rule added later: Re-allocate keeps the approved charge and remakes the drafts\n";
[$c, $b] = act($marco, '/usage/approve.php', ['charge' => (int) $ch[0]['id']]);
ok($c === 200 && usage_row((int) $ch[0]['id'])['status'] === 'approved', 'Marco approves the Acme anthropic charge (60.00)');
$approved = (int) $ch[0]['id'];
$draftIds = array_map('intval', array_column(array_slice($ch, 1), 'id'));
[$c, $b] = rule_req($marco, ['name' => 'SMOKE too much', 'engagement' => $acme, 'agent' => 901, 'share_pct' => '50']);
$r4 = (int) $b['record_id'];
$stateBefore = q('SELECT id, status FROM usage_charges WHERE statement_id = :s ORDER BY id', ['s' => $aug['id']]);
[$c, $b] = act($marco, '/usage/os/allocate.php', ['period' => '2026-08']);
ok($c === 422 && str_contains(msg($b), 'The rules for line 1 (anthropic, Researcher) share out 150.00 % — more than the whole; fix the rules'), 'rules over 100 %: refused naming the line (' . msg($b) . ')');
ok(q('SELECT id, status FROM usage_charges WHERE statement_id = :s ORDER BY id', ['s' => $aug['id']]) === $stateBefore, 'and nothing changed (the drafts were not remade)');
[$c, $b] = act($marco, '/settings/allocation-rules/delete.php', ['rule' => $r4]);
ok($c === 200 && (int) one('SELECT count(*) FROM allocation_rules WHERE id = :r', ['r' => $r4]) === 0, 'allocation_rule_delete removes the over-sharing rule');
$log = activity('allocation_rule.delete', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['before'], true)['name'] === 'SMOKE too much' && (int) $log[0]['engagement_id'] === $acme, 'allocation_rule.delete logged with the engagement');
[$c, $b] = rule_req($marco, ['name' => 'SMOKE Content to Beta', 'engagement' => $beta, 'department' => 8]);
$r3 = (int) $b['record_id'];
[$c, $b] = act($marco, '/usage/os/allocate.php', ['period' => '2026-08']);
ok($c === 200 && $b['charges'] === 4 && $b['kept'] === 1 && $b['allocated_amount'] === '180.33' && $b['remainder'] === '0.01', 'Re-allocate with the Content rule: four drafts remade, the approved one kept; 180.33 placed, the remainder is the cent');
$after = q('SELECT id, status, cost_amount, engagement_id FROM usage_charges WHERE statement_id = :s ORDER BY id', ['s' => $aug['id']]);
ok(count($after) === 5 && usage_row($approved)['status'] === 'approved' && usage_row($approved)['cost_amount'] === '60.00' && array_intersect($draftIds, array_column($after, 'id')) === [], 'five charges now: the approved one kept as it was, the three old drafts gone, four new drafts');
$costs = array_map(fn ($r) => $r['cost_amount'], q("SELECT cost_amount FROM usage_charges WHERE statement_id = :s AND status = 'draft' ORDER BY cost_amount", ['s' => $aug['id']]));
ok($costs === ['12.13', '18.20', '40.00', '50.00'], 'the drafts: Acme openai 18.20, Beta anthropic 40.00 (cost + 25 %) and 50.00 (the Writer\'s line at cost), Beta openai 12.13');
$ln = q('SELECT line_no, allocated_amount FROM ai_statement_lines WHERE statement_id = :s ORDER BY line_no', ['s' => $aug['id']]);
ok(array_column($ln, 'allocated_amount') === ['100.00', '30.33', '50.00'], 'the lines: 100.00, 30.33, 50.00 allocated (the approved piece counted once)');
ok((int) one('SELECT count(*) FROM ai_statement_allocations WHERE statement_id = :s', ['s' => $aug['id']]) === 5, 'five pieces');
$log = activity('ai_statement.allocate', $since);
ok(count($log) === 2 && json_decode((string) $log[1]['after'], true)['kept'] === 1 && json_decode((string) $log[1]['after'], true)['remainder'] === '0.01', 'the second ai_statement.allocate row says kept 1, remainder 0.01');

echo "7. Void returns a piece to the remainder\n";
$beo = (int) one("SELECT u.id FROM usage_charges u JOIN usage_providers p ON p.id = u.provider_id WHERE u.statement_id = :s AND p.provider_key = 'openai' AND u.engagement_id = :e", ['s' => $aug['id'], 'e' => $beta]);
[$c, $b] = act($marco, '/usage/void.php', ['charge' => $beo, 'reason' => 'SMOKE we absorb the OpenAI tokens']);
$ln = q('SELECT line_no, allocated_amount FROM ai_statement_lines WHERE statement_id = :s ORDER BY line_no', ['s' => $aug['id']]);
ok($c === 200 && usage_row($beo)['status'] === 'void' && array_column($ln, 'allocated_amount') === ['100.00', '18.20', '50.00'], 'voiding Beta\'s OpenAI charge: the line\'s allocated amount falls to 18.20');
[$c, $d] = screen($marco, '/usage/os?period=2026-08');
ok($d['lines'][1]['remainder'] === '12.14' && $d['month']['remainder'] === '12.14', 'the remainder shows it again: 12.14 (the 12.13 and the cent)');

echo "8. A changed document for an allocated month is refused\n";
$changed = $docs;
$changed['2026-08']['lines'][0]['amount'] = '100.5000';
set_ledger($changed);
$hash = statement_row('2026-08')['document_hash'];
[$c, $b] = act($marco, '/usage/os/pull.php', ['period' => '2026-08']);
ok($c === 422 && str_contains(msg($b), 'Statement 2026-08 was allocated from a different document') && statement_row('2026-08')['document_hash'] === $hash, 'pulling a changed 2026-08: 422 in the database\'s words, the kept document untouched (' . substr(msg($b), 0, 90) . '…)');
@unlink($klog);
[$c, $b] = act($marco, '/usage/os/pull.php', []);
ok($c === 200 && asked() === ['list', '2026-09'], 'the plain Pull never asks again for a closed month it holds');
set_ledger($docs);

echo "9. The open month closes\n";
$docs['2026-09'] = ledger_doc('2026-09', 'closed', [ledger_line('anthropic', 901, 'Researcher', 7, 'AI Strategy', '13.0000'), ledger_line('anthropic', 902, 'Writer', 8, 'Content', '2.0000')]);
set_ledger($docs);
[$c, $b] = act($marco, '/usage/os/pull.php', []);
ok($c === 200 && count($b['months']) === 1 && $b['months'][0]['period'] === '2026-09' && $b['months'][0]['kernel_status'] === 'closed' && $b['months'][0]['changed'] === true && $b['months'][0]['lines'] === 2, 'Pull again: the month the OS has since closed is replaced by its closed document (changed, two lines)');
[$c, $b] = act($marco, '/usage/os/allocate.php', ['period' => '2026-09']);
$sep = statement_row('2026-09');
ok($c === 200 && $b['charges'] === 3 && $b['allocated_amount'] === '15.00' && $b['remainder'] === '0.00', 'and it allocates: 7.80 + 5.20 of the Researcher\'s 13.00, the Writer\'s 2.00 to Beta; nothing remains');
